         SELECT "asset_list"."tenant_id",
            "asset_list"."asset_id",
            "asset_list"."site_id",
            "asset_list"."gai",
            "asset_list"."name",
            "asset_list"."loc_path",
            "asset_list"."func_path",
            "asset_list"."net_path",
            "asset_list"."dev_path",
            "asset_list"."asset_type",
            "asset_list"."lat",
            "asset_list"."lon",
            "asset_list"."storey",
            "asset_list"."description",
            "asset_list"."tags",
            "asset_list"."ar",
            "asset_list"."urldoc",
            "asset_list"."allowed_inactivity",
            "asset_list"."active",
            "asset_list"."archived",
            "asset_list"."acl_access",
            "asset_list"."acl_permissions"
           FROM "public"."asset_list"
        ), "asset_pkeys" AS (
         SELECT "asset_pkey"."tenant_id",
            "asset_pkey"."asset_id",
            "array_agg"("asset_pkey"."uin") AS "uin"
           FROM "public"."asset_pkey"
          WHERE ("asset_pkey"."tenant_id" = "public"."token_tenant"())
          GROUP BY "asset_pkey"."tenant_id", "asset_pkey"."asset_id"
        )
 SELECT "asset"."tenant_id",
    "asset"."asset_id",
    "asset"."name",
    "asset"."site_id",
    "asset"."loc_path",
    "asset"."func_path",
    "asset"."net_path",
    "asset"."dev_path",
    "asset"."asset_type",
    "asset"."allowed_inactivity",
    "asset"."active",
        CASE
            WHEN "asset"."acl_access" THEN "asset"."gai"
            ELSE NULL::"text"
        END AS "gai",
        CASE
            WHEN "asset"."acl_access" THEN "asset"."lat"
            ELSE NULL::double precision
        END AS "lat",
        CASE
            WHEN "asset"."acl_access" THEN "asset"."lon"
            ELSE NULL::double precision
        END AS "lon",
        CASE
            WHEN "asset"."acl_access" THEN "asset"."storey"
            ELSE NULL::smallint
        END AS "storey",
        CASE
            WHEN "asset"."acl_access" THEN "asset"."description"
            ELSE NULL::"text"
        END AS "description",
        CASE
            WHEN "asset"."acl_access" THEN "asset"."tags"
            ELSE NULL::"text"[]
        END AS "tags",
        CASE
            WHEN "asset"."acl_access" THEN "asset"."ar"
            ELSE NULL::boolean
        END AS "ar",
        CASE
            WHEN "asset"."acl_access" THEN "asset"."urldoc"
            ELSE NULL::"jsonb"
        END AS "urldoc",
        CASE
            WHEN "asset"."acl_access" THEN "asset_pkeys"."uin"
            ELSE NULL::"text"[]
        END AS "uin",
    NULL::"text" AS "device_pkey",
    "asset"."acl_permissions",
    "asset"."acl_access"
   FROM ("asset"
     LEFT JOIN "asset_pkeys" ON (("asset"."acl_access" AND ("asset_pkeys"."tenant_id" = "asset"."tenant_id") AND ("asset_pkeys"."asset_id" = "asset"."asset_id"))));


