CREATE VIEW "audit"."heap" AS
 SELECT "tenant_id",
    "asset_id",
    "subtype",
    "his",
    "ts",
    "data",
    "diff",
    "update_cnt",
    "update_cnt_reset_ts",
    "pid",
    "source"
   FROM "public"."heap";


--
-- Name: heap(integer, "text", "json", "text"[]); Type: FUNCTION; Schema: api; Owner: -
--

CREATE FUNCTION "api"."heap"("asset_id" integer, "subtype" "text", "data" "json", "diff" "text"[] DEFAULT NULL::"text"[]) RETURNS SETOF "audit"."heap"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    _data json;
    _tenant uuid := token_tenant(); -- license-aware; NULL on expired unless superadmin
BEGIN
    IF _tenant IS NULL THEN
        RAISE sqlstate '28000'
        USING message = 'access denied', hint = 'license inactive';
    END IF;

    -- accept only valid keys in the subtype
    SELECT
        coalesce((
            SELECT
                json_object_agg(key, value)
            FROM
                json_each($3),
                attribute_schema s
            WHERE
                s.tenant_id = a.tenant_id
                AND s.asset_type = a.asset_type
                AND s.subtype = $2
                AND s.attribute = key
            GROUP BY (s.asset_type, s.subtype)), '{}'::json) AS data
    FROM
        public.asset a
    WHERE
        a.tenant_id = _tenant
        AND a.asset_id = $1
        AND acl_check_tag_access(a.tags,2)
    INTO
        _data;

    IF _data IS NULL THEN
        RAISE sqlstate '28000'
        USING message = 'access denied', hint = 'no right to modify the asset-data';
    END IF;

    -- "upsert" as 2 separate statements to call the trigger-functions
    UPDATE
        audit.heap h
    SET
        ts = now(),
        data = coalesce(h.data,'{}'::jsonb) || _data::jsonb,
        diff = $4
    WHERE
        h.tenant_id = _tenant
        AND h.asset_id = $1
        AND h.subtype = $2;

    IF NOT FOUND THEN
        -- update failed?
        INSERT INTO audit.heap (tenant_id, asset_id, subtype, ts, data, diff)
            VALUES (_tenant, $1, $2, now(), _data, $4);
    END IF;

    RETURN QUERY
        SELECT * FROM audit.heap h WHERE h.asset_id = $1 AND h.subtype = $2;
END
$_$;


