--
-- Name: asset_but(); Type: FUNCTION; Schema: import; Owner: -
--

CREATE FUNCTION "import"."asset_but"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- set information, when a new asset was created and assigned
    IF OLD.asset_id IS NULL AND NEW.asset_id IS NOT NULL THEN
        NEW.imported_by = token_user();
        NEW.imported_at = now();
    END IF;

    NEW.modified_by  = token_user();
    NEW.modified_at  = now();
    NEW.modified_cnt = NEW.modified_cnt + 1;

    RETURN NEW;
END;
$$;


--
-- Name: acl_check_tag_access("text"[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."acl_check_tag_access"("tags" "text"[], "mask" integer DEFAULT 1) RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $_$
    SELECT
        count(*) > 0 -- returns the real true/false
    FROM
        token
    WHERE
        entitlements = 'superadmin' -- access to every tag allowed
        OR
        EXISTS (
            SELECT
            FROM
                (
                    SELECT
                        role_id,
                        access_untagged
                    FROM
                        public.acl_role
                    WHERE
                        role_id = token.role_id::integer
                ) acl_role
                LEFT JOIN public.acl_tag_entries USING (role_id)
            WHERE
                (
                    -- write access to the untagged assets
                    (tags IS NULL OR array_length(tags,1) IS NULL)
                    AND
                    acl_role.access_untagged IS TRUE
                )
                OR
                (
                    name = ANY(tags)
                    AND role_id = token.role_id::integer
                    AND $2 = mask & $2
                )
        )
$_$;


