--
-- Name: alarm_cfg_but(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."alarm_cfg_but"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- remove the "old" alarm-entry, if any
    IF TG_OP = 'UPDATE' AND NEW.asset_id <> OLD.asset_id THEN
        DELETE FROM public.alarm
        WHERE alarm_id = OLD.alarm_id;
    END IF;

    NEW.modified_by = COALESCE(token_user()::text, token_key());
    NEW.modified_at = now();
    NEW.modified_by_api = token_key() IS NOT NULL;

    IF TG_OP = 'INSERT' OR NEW.tags IS DISTINCT FROM OLD.tags THEN
        -- remove tags, if not valid and sort the result by category
        NEW.tags = tags_sort(NEW.tenant_id, NEW.tags);
    END IF;

    RETURN NEW;
END
$$;


