--
-- Name: alarm_id("public"."digital_twin_data"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."alarm_id"("public"."digital_twin_data") RETURNS integer
    LANGUAGE "sql" IMMUTABLE STRICT
    AS $_$
    SELECT DISTINCT ON (a.asset_id)
        alarm_id
    FROM
        public.alarm a
        JOIN public.digital_twin_content c USING (asset_id)
    WHERE (
        -- $1.show_alarm is true and
        a.subtype = $1.subtype
        AND (a.attribute = $1.attribute
            OR $1.attribute IS NULL)
    )
    ORDER BY
        asset_id,
        prio ASC
$_$;


--
-- Name: asset_delete_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."asset_delete_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF token_user () IS NOT NULL THEN -- any "API" role only marks them deleted

        -- SET ROLE "admin"; -- AL: temporary, to bypass SELECT policy (needed by UPDATE)

        -- add some random bytes and clean up device primary key
        UPDATE
            public.asset
        SET
            gai         = gai || '-' || encode(gen_random_bytes(8), 'hex'),
            deleted_by  = token_user(),
            deleted_at  = now() -- that affects SELECT policy
        WHERE
            tenant_id = OLD.tenant_id
            AND asset_id = OLD.asset_id;

        -- cleanup of the associated external IDs
        DELETE FROM public.asset_pkey
        WHERE tenant_id = OLD.tenant_id AND asset_id = OLD.asset_id;

        -- cleanup the alarm config
        DELETE FROM public.alarm_cfg
        WHERE tenant_id = OLD.tenant_id AND asset_id = OLD.asset_id;

        RETURN NULL; -- return null, so that the record is not removed from database
    ELSE
        RETURN OLD;

    END IF;
END;
$$;


--
-- Name: asset_type_but(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."asset_type_but"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.tenant_id   = COALESCE(NEW.tenant_id, token_tenant());
    NEW.rec_class   = COALESCE(NEW.rec_class, 'Not_Defined'); -- an explicit NULL from a client bypasses the DEFAULT
    NEW.category    = COALESCE(NEW.category, public.asset_type_category_default(NEW.tenant_id));
    NEW.poi_icon    = nullif(NEW.poi_icon, '');  -- an empty string is no icon
    NEW.type_icon   = nullif(NEW.type_icon, '');
    NEW.modified_by = token_user();
    NEW.modified_at = now();

    RETURN NEW;
END;
$$;


--
-- Name: asset_type_category_but(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."asset_type_category_but"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.tenant_id   = COALESCE(NEW.tenant_id, token_tenant());
    NEW.modified_by = token_user();
    NEW.modified_at = now();

    -- the tree stays acyclic: a category is neither its own parent nor placed below one of its sub-categories
    -- (the walk runs on the stored names, a rename in the same statement is not applied yet)
    IF NEW.parent IS NOT NULL
       AND (NEW.parent = NEW.category
            OR (TG_OP = 'UPDATE' AND NEW.parent IN (SELECT public.asset_type_category_descendants(OLD.tenant_id, OLD.category)))) THEN
        RAISE EXCEPTION 'category "%" cannot be its own parent or sit below one of its sub-categories', NEW.category
            USING ERRCODE = 'PT400';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: asset_type_category_default("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."asset_type_category_default"("_tid" "uuid") RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    INSERT INTO public.asset_type_category (tenant_id, category, translation, custom)
    VALUES (_tid, 'custom', '{"de": "Eigene Vorlagen", "en": "Custom templates"}', FALSE)
    ON CONFLICT (tenant_id, category) DO NOTHING;

    RETURN 'custom';
END;
$$;


--
-- Name: asset_type_category_descendants("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."asset_type_category_descendants"("_tid" "uuid", "_category" "text") RETURNS SETOF "text"
    LANGUAGE "sql" STABLE
    AS $$
    WITH RECURSIVE sub AS (
        SELECT atc.category FROM public.asset_type_category atc WHERE atc.tenant_id = _tid AND atc.category = _category
        UNION
        SELECT c.category FROM public.asset_type_category c JOIN sub ON (c.parent = sub.category) WHERE c.tenant_id = _tid
    )
    SELECT category FROM sub;
$$;


--
-- Name: attribute_schema_aut(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."attribute_schema_aut"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    INSERT INTO public.heap (tenant_id, asset_id, subtype, ts, data)
    SELECT
        types.tenant_id,
        asset.asset_id,
        'property',
        now(),
        jsonb_object_agg(sch.attribute, sch."default" -> 'value')
    FROM (
        SELECT DISTINCT tenant_id, asset_type
        FROM added
        WHERE enable IS TRUE
    ) AS types
        JOIN public.attribute_schema sch
            USING (tenant_id, asset_type)
        JOIN public.asset asset
            USING (tenant_id, asset_type)
    WHERE
        sch.subtype = 'property'
        AND sch.property_category IS NOT NULL
        AND asset.archived IS FALSE
    GROUP BY
        types.tenant_id, asset.asset_id
    ON CONFLICT (tenant_id, asset_id, subtype) DO UPDATE
        SET ts   = excluded.ts,
            data = jsonb_merge(heap.data, excluded.data),
            -- changed keys, formerly computed by the heap_diff trigger; compared against the
            -- merged result because jsonb_merge may change a top-level key through nested values
            diff = (SELECT array_agg(o.key)
                    FROM jsonb_each(heap.data) o
                        JOIN jsonb_each(jsonb_merge(heap.data, excluded.data)) n ON n.key = o.key
                    WHERE o.value IS DISTINCT FROM n.value);

    --
    -- Create empty heap records for newly created subtypes of an asset type
    --
    INSERT INTO public.heap (tenant_id, asset_id, subtype, data)
    SELECT
        types.tenant_id,
        a.asset_id,
        types.subtype,
        '{}'::jsonb
    FROM (
        SELECT DISTINCT tenant_id, asset_type, subtype
        FROM added
        WHERE enable IS TRUE
            AND subtype IN ('input', 'status', 'info')
    ) AS types
        JOIN public.asset a
            USING (tenant_id, asset_type)
    ON CONFLICT (tenant_id, asset_id, subtype) DO NOTHING;

    RETURN NULL;
END;
$$;


--
-- Name: attribute_schema_but(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."attribute_schema_but"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.tenant_id   = COALESCE(NEW.tenant_id, token_tenant());
    NEW.modified_by = token_user();
    NEW.modified_at = now();

    -- only a Point class classifies an attribute (the FK alone would accept Building)
    IF NEW.rec_class IS NOT NULL AND NOT public.rec_class_is_a(NEW.rec_class, 'Point') THEN
        RAISE EXCEPTION 'attribute class "%" is not a Point class', NEW.rec_class
            USING ERRCODE = 'PT400';
    END IF;

    -- transition: the quantity from the unit (the specific fact) or the class while consumers still read attribute_type
    IF NEW.attribute_type IS NULL THEN
        NEW.attribute_type = COALESCE((SELECT u.category FROM public.unit u WHERE u.unit_id = NEW.unit_id),
                                      (SELECT rc.quantity FROM public.rec_class rc WHERE rc.rec_class = NEW.rec_class));
    END IF;

    RETURN NEW;
END;
$$;


