--
-- Name: eliona_tenant_bdt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."eliona_tenant_bdt"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF current_setting('eliona.tenant_purge', true) = OLD.tenant_id::text THEN
        RETURN OLD; -- tenant_purge(): really delete
    END IF;

    UPDATE public.eliona_tenant
    SET deleted_at = coalesce(deleted_at, now()),
        deleted_by = coalesce(deleted_by, token_user()::text, current_user::text)
    WHERE tenant_id = OLD.tenant_id;

    RETURN NULL; -- skip the delete
END;
$$;


