--
-- Name: heap_counter(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."heap_counter"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Das ist ein reiner update-Trigger.
    -- Das allererste Insert würde, selbst wenn es eine Rasterung hätte, würde hier nicht ankommen.
    -- Insert ... on conflict .. do update schon.
    -- Leider würde dabei ein on insert or update - Trigger zweimal aufgerufen!
    -- Ein After-Trigger hat dieses Problem nicht, der wird nur zweimal markiert und hinterher einmal aufgerufen.
    NEW.update_cnt = NEW.update_cnt + 1;
    NEW.pid        = pg_backend_pid();
    IF (current_query() !~ 'source') THEN
        NEW.source = NULL; -- TODO: reset "source" spec, if not in the update
    END IF;

    RETURN NEW;
END
$$;


--
-- Name: icon_but(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."icon_but"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF TG_OP = 'INSERT' AND token_tenant() IS NOT NULL THEN
        NEW.tenant_id = token_tenant();
        NEW.custom    = TRUE;
    END IF;

    IF NEW.tenant_id IS NOT NULL
       AND (TG_OP = 'INSERT' OR NEW.name IS DISTINCT FROM OLD.name)
       AND EXISTS (SELECT FROM public.icon i WHERE i.tenant_id IS NULL AND i.name = NEW.name) THEN
        RAISE EXCEPTION 'icon "%" is delivered by the platform', NEW.name
            USING ERRCODE = 'PT409';
    END IF;

    NEW.modified_by = token_user();
    NEW.modified_at = now();

    RETURN NEW;
END;
$$;


--
-- Name: icon_effective("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."icon_effective"("_tid" "uuid", "_name" "text", "_rec_class" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
    IF _name IS NOT NULL
       AND EXISTS (SELECT FROM public.icon i WHERE i.name = _name AND (i.tenant_id IS NULL OR i.tenant_id = _tid)) THEN
        RETURN _name;
    END IF;

    RETURN coalesce(public.rec_class_icon(_rec_class), 'default');
END;
$$;


--
-- Name: jsonb_merge("jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."jsonb_merge"("data" "jsonb", "attr" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
    SELECT
        CASE jsonb_typeof($1)
        WHEN 'object' THEN
            CASE jsonb_typeof($2)
            WHEN 'object' THEN
            (
                SELECT
                    jsonb_object_agg(k,
                        CASE
                            WHEN a.v IS NULL THEN d.v
                            WHEN d.v IS NULL THEN a.v
                            ELSE public.jsonb_merge (d.v, a.v)
                        END
                    )
                FROM
                    jsonb_each($1) d(k, v)
                    FULL JOIN jsonb_each($2) a(k, v) USING (k)
            )
            ELSE
                coalesce(nullif($1,'null'::jsonb),$2)
            END
        WHEN 'array' THEN
            (SELECT
                jsonb_agg(items.val)
            FROM (
                SELECT jsonb_array_elements($1) AS val
                UNION
                SELECT jsonb_array_elements($2) AS val
            ) AS items)
        ELSE
            coalesce(nullif($1,'null'::jsonb),$2)
        END;
$_$;


--
-- Name: keyauth_secret(integer, "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."keyauth_secret"("n" integer, "alphabet" "text" DEFAULT 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-!%$@'::"text") RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    out text := '';
    m int := length(alphabet);
    bytes bytea;
    b int;
    l int := 256 - (256 % m); -- rejection sampling limit
BEGIN
    IF n <= 0 THEN
        RETURN '';
    END IF;
    LOOP
        -- some oversampling to compensate for rare distortions
        bytes := gen_random_bytes(greatest (n * 2, 32));

        FOR i IN 0..length(bytes) - 1 LOOP
            b := get_byte(bytes, i);
            IF b < l THEN
                out := out || substr(alphabet, (b % m) + 1, 1);
                IF length(out) = n THEN
                    RETURN out;
                END IF;
            END IF;
        END LOOP;
    END LOOP;
END;
$$;


--
-- Name: property_adt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."property_adt"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    attr text;
    atype text;
    tid uuid;
BEGIN
    -- tenant_purge(): the assets go with the same cascade, their heap rows with them
    IF current_setting('eliona.tenant_purge', true) = OLD.tenant_id::text THEN
        RETURN NULL;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF NEW.enable IS TRUE THEN
            RETURN NULL;
        ELSE
            attr = NEW.attribute;
            atype = NEW.asset_type;
            tid = NEW.tenant_id;
        END IF;
    ELSE
        attr = OLD.attribute;
        atype = OLD.asset_type;
        tid = OLD.tenant_id;
    END IF;

    -- asset_type names repeat across tenants: without the tenant the strip hit every tenant's heap
    UPDATE
        public.heap h
    SET
        data = h.data - attr
    FROM
        public.asset a
    WHERE
        a.tenant_id = tid
        AND a.asset_type = atype
        AND h.tenant_id = a.tenant_id
        AND h.asset_id = a.asset_id
        AND h.data ? attr;

    RETURN NULL;
END;
$$;


--
-- Name: rec_class_icon("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."rec_class_icon"("_rec_class" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
    _class text = _rec_class;
    _icon  text;
    _depth integer = 0;
BEGIN
    WHILE _class IS NOT NULL AND _depth < 32 LOOP
        SELECT
            rc.icon, rc.parent_rec_class
        INTO
            _icon, _class
        FROM
            rec_class rc
        WHERE
            rc.rec_class = _class;
        IF _icon IS NOT NULL THEN
            RETURN _icon;
        END IF;
        _depth = _depth + 1;
    END LOOP;

    RETURN NULL;
END;
$$;


--
-- Name: rec_class_is_a("text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."rec_class_is_a"("_rec_class" "text", "_ancestor" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
    WITH RECURSIVE up AS (
        SELECT rc.rec_class, rc.parent_rec_class FROM rec_class rc WHERE rc.rec_class = _rec_class
        UNION
        SELECT p.rec_class, p.parent_rec_class FROM rec_class p JOIN up ON (p.rec_class = up.parent_rec_class)
    )
    SELECT EXISTS (SELECT FROM up WHERE up.rec_class = _ancestor);
$$;


--
-- Name: setup_asset_heap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."setup_asset_heap"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- set default validity
    UPDATE public.asset
    SET
        active = NULLIF(at.allowed_inactivity IS NOT NULL, FALSE)
    FROM
        asset_type at
    WHERE
        asset.asset_id = NEW.asset_id
        AND at.asset_type = NEW.asset_type;

    INSERT INTO public.heap (tenant_id, asset_id, subtype, data)
    SELECT
        NEW.tenant_id,
        NEW.asset_id,
        subtype,
        '{}'::jsonb
    FROM
        public.attribute_schema
    WHERE
        tenant_id = NEW.tenant_id
        AND asset_type = NEW.asset_type
        AND subtype IN ('input', 'status', 'info', 'output')
        AND enable = TRUE
    GROUP BY
        subtype;

    -- default properties
    INSERT INTO public.heap (tenant_id, asset_id, subtype, data)
    SELECT
        NEW.tenant_id,
        NEW.asset_id,
        subtype,
        json_object_agg(attribute, "default" -> 'value')
    FROM
        public.attribute_schema
    WHERE
        tenant_id = NEW.tenant_id
        AND asset_type = NEW.asset_type
        AND subtype = 'property'
        AND property_category IS NOT NULL
        AND enable = TRUE
    GROUP BY
        subtype;

    RETURN NEW;
END;
$$;


--
-- Name: tags_but(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."tags_but"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    cat text;
BEGIN
    NEW.tenant_id   = COALESCE(NEW.tenant_id, token_tenant());
    NEW.modified_by = token_user();
    NEW.modified_at = now();
    -- replacement for multi-column foreign key (tenant_id, category_id)
    IF NEW.category_id IS NOT NULL THEN
        SELECT c.category INTO cat FROM public.tag_category c WHERE c.tenant_id = NEW.tenant_id AND c.category_id = NEW.category_id AND NOT c.custom;
        IF NOT FOUND AND NOT EXISTS (SELECT FROM public.tag_category c WHERE c.tenant_id = NEW.tenant_id AND c.category_id = NEW.category_id) THEN
            RAISE EXCEPTION 'Category % does not belong to tenant %', NEW.category_id, NEW.tenant_id USING ERRCODE = 'PT400';
        END IF;
        -- platform categories name their tags "<category>:<value>" (D4): asset.tags holds names only
        IF cat IS NOT NULL AND left(NEW.name, length(cat) + 1) <> cat || ':' THEN
            NEW.name = cat || ':' || NEW.name;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: tags_sort("uuid", "text"[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."tags_sort"("tenant_id" "uuid", "tags" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" STABLE
    AS $_$
    SELECT
        array_agg(name ORDER BY seq NULLS LAST, category, name)
    FROM
        public.tags t
        LEFT JOIN public.tag_category USING (tenant_id, category_id)
    WHERE
        t.tenant_id = $1
        AND t.name = ANY($2);
$_$;


