    RETURN NEW;
END
$$;


--
-- Name: tenant_purge("uuid", interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."tenant_purge"("tid" "uuid", "grace" interval DEFAULT '7 days'::interval) RETURNS TABLE("relation" "text", "leftover" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'cron', 'audit'
    AS $_$
DECLARE
    tenant_schema text := tenant_schema_name(tid);
    rec record;
BEGIN
    IF grace > interval '0' THEN
        IF NOT EXISTS (SELECT FROM public.eliona_tenant WHERE tenant_id = tid AND deleted_at IS NOT NULL) THEN
            RAISE EXCEPTION 'tenant % is not marked for deletion (pass grace ''0'' to purge anyway)', tid;
        END IF;
        IF NOT EXISTS (SELECT FROM public.eliona_tenant WHERE tenant_id = tid AND deleted_at <= now() - grace) THEN
            RAISE NOTICE 'tenant % is still within the grace period of %', tid, grace;
            RETURN;
        END IF;
    END IF;

    -- never queue behind busy writers; the caller retries on lock_not_available (a caller with its
    -- own bound, the cron path, keeps it)
    IF current_setting('lock_timeout') = '0' THEN
        PERFORM set_config('lock_timeout', '3s', true);
    END IF;

    -- 0. app schemas (booking, device_simulator, ...): tables with a tenant_id uuid column; no consumer
    --    of the tenant events cleans them, most carry no tenant FK. First, while nothing else is locked;
    --    the staging schemas of backup/restore and import stay untouched (a restore purges first)
    FOR rec IN (
        SELECT n.nspname, c.relname
        FROM pg_class c
            JOIN pg_namespace n ON (n.oid = c.relnamespace)
            JOIN pg_attribute a ON (a.attrelid = c.oid AND a.attname = 'tenant_id' AND NOT a.attisdropped
                                    AND a.atttypid = 'uuid'::regtype)
        WHERE n.nspname NOT IN ('public', 'cron', 'audit', 'backup', 'import', 'sqitch', 'information_schema')
          AND n.nspname NOT LIKE 'pg\_%'
          AND n.nspname NOT LIKE '\_timescaledb%'
          AND n.nspname NOT LIKE 'timescaledb\_%'
          AND n.nspname NOT LIKE 'tenant\_%'
          AND c.relkind IN ('r', 'p')
          AND NOT c.relispartition
        ORDER BY 1, 2
    )
    LOOP
        EXECUTE format('DELETE FROM %I.%I WHERE tenant_id = $1', rec.nspname, rec.relname) USING tid;
    END LOOP;

    -- 1. tenant row: cascades through every table with a tenant foreign key (incl. the rows of
    --    the partitioned tables asset/alarm/alarm_history/user_notification and their dependents).
    --    The local setting lets the delete through the lazy delete trigger (eliona_tenant_bdt)
    PERFORM set_config('eliona.tenant_purge', tid::text, true);
    DELETE FROM public.eliona_tenant WHERE tenant_id = tid;

    -- 2. tables that reference the tenant only by column (no FK) and are not partitioned by
    --    tenant: heap, calculator, asset_pkey, audit_log_comment, jobqueue, ... - the partition
    --    bound rows are handled in step 3/4, deleting them row by row would be far more expensive
    FOR rec IN (
        SELECT n.nspname, c.relname
        FROM pg_class c
            JOIN pg_namespace n ON (n.oid = c.relnamespace)
            JOIN pg_attribute a ON (a.attrelid = c.oid AND a.attname = 'tenant_id' AND NOT a.attisdropped)
        WHERE n.nspname IN ('public', 'cron', 'audit')
          AND c.relkind IN ('r', 'p')
          AND NOT EXISTS (SELECT FROM pg_inherits i WHERE i.inhrelid = c.oid) -- not a partition itself
          AND NOT EXISTS (SELECT FROM pg_constraint f
                          WHERE f.conrelid = c.oid AND f.contype = 'f'
                            AND f.confrelid = 'public.eliona_tenant'::regclass)
          AND NOT EXISTS (SELECT FROM pg_tables t
                          WHERE t.schemaname = tenant_schema AND t.tablename = c.relname)
        ORDER BY 2
    )
    LOOP
        EXECUTE format('DELETE FROM %I.%I WHERE tenant_id = $1', rec.nspname, rec.relname) USING tid;
    END LOOP;

    -- 3. partitions living in the tenant schema: detach and drop (no row deletes); the tenant views on
    --    them (alarm_data, ...) go first, DROP TABLE refuses while they exist and step 5 drops them anyway
    FOR rec IN (
        SELECT c.relname, c.relkind
        FROM pg_class c
            JOIN pg_namespace n ON (n.oid = c.relnamespace)
        WHERE n.nspname = tenant_schema
          AND c.relkind IN ('v', 'm')
    )
    LOOP
        EXECUTE format('DROP %s IF EXISTS %I.%I CASCADE',
            CASE rec.relkind WHEN 'm' THEN 'MATERIALIZED VIEW' ELSE 'VIEW' END, tenant_schema, rec.relname);
    END LOOP;

    FOR rec IN (
        SELECT i.inhparent::regclass AS parent, c.relname
        FROM pg_class c
            JOIN pg_namespace n ON (n.oid = c.relnamespace)
            JOIN pg_inherits i ON (i.inhrelid = c.oid)
        WHERE n.nspname = tenant_schema
          AND c.relkind IN ('r', 'p') -- pg_inherits also lists index partitions
    )
    LOOP
        EXECUTE format('ALTER TABLE %s DETACH PARTITION %I.%I', rec.parent, tenant_schema, rec.relname);
        EXECUTE format('DROP TABLE %I.%I', tenant_schema, rec.relname);
    END LOOP;

    -- 4. partitioned parents without tenant FK (audit_log, ...): rows that ended up in the
    --    default partition - cheap now that the tenant partition is gone
    FOR rec IN (
        SELECT n.nspname, c.relname
        FROM pg_class c
            JOIN pg_namespace n ON (n.oid = c.relnamespace)
            JOIN pg_attribute a ON (a.attrelid = c.oid AND a.attname = 'tenant_id' AND NOT a.attisdropped)
        WHERE n.nspname IN ('public', 'cron', 'audit')
          AND c.relkind = 'p'
          AND NOT EXISTS (SELECT FROM pg_inherits i WHERE i.inhrelid = c.oid)
          AND NOT EXISTS (SELECT FROM pg_constraint f
                          WHERE f.conrelid = c.oid AND f.contype = 'f'
                            AND f.confrelid = 'public.eliona_tenant'::regclass)
    )
    LOOP
        EXECUTE format('DELETE FROM %I.%I WHERE tenant_id = $1', rec.nspname, rec.relname) USING tid;
    END LOOP;

    -- 5. tenant schema with the tenant-local objects (trend hypertable, views); CASCADE covers
    --    the dependent views, the TimescaleDB event triggers take care of chunks and catalog
    EXECUTE format('DROP SCHEMA IF EXISTS %I CASCADE', tenant_schema);

    -- 6. leftover scan over every schema but the system and staging ones (loop, not a set query: the
    --    planner would evaluate the count before the pg_attribute join and hit tables without tenant_id);
    --    uuid columns named *tenant_id besides tenant_id (eliona_tenant_id, ...) are reported, not purged
    FOR rec IN (
        SELECT n.nspname, c.relname, a.attname
        FROM pg_class c
            JOIN pg_namespace n ON (n.oid = c.relnamespace)
            JOIN pg_attribute a ON (a.attrelid = c.oid AND a.attname LIKE '%tenant\_id' AND NOT a.attisdropped
                                    AND a.atttypid = 'uuid'::regtype)
        WHERE n.nspname NOT IN ('backup', 'import', 'sqitch', 'information_schema')
          AND n.nspname NOT LIKE 'pg\_%'
          AND n.nspname NOT LIKE '\_timescaledb%'
          AND n.nspname NOT LIKE 'timescaledb\_%'
          AND n.nspname NOT LIKE 'tenant\_%'
          AND c.relkind IN ('r', 'p')
          AND NOT c.relispartition
        ORDER BY 1, 2, 3
    )
    LOOP
        EXECUTE format('SELECT count(*) FROM %I.%I WHERE %I = $1', rec.nspname, rec.relname, rec.attname)
            USING tid INTO leftover;
        IF leftover > 0 THEN
            relation := rec.nspname || '.' || rec.relname
                || CASE WHEN rec.attname <> 'tenant_id' THEN '.' || rec.attname ELSE '' END;
            RETURN NEXT;
        END IF;
    END LOOP;
END;
$_$;


