CREATE FUNCTION "public"."ticket_template"("tenant_id" "uuid") RETURNS "json"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    ticketmail json := (SELECT t.ticketmail FROM public.templategroup t WHERE t.tenant_id = $1 AND custom AND enabled);
BEGIN
    IF ticketmail IS NULL THEN -- fallback
        SELECT t.ticketmail INTO ticketmail FROM public.templategroup t WHERE t.tenant_id = $1 AND NOT custom AND enabled;
    END IF;

    RETURN ticketmail;
END
$_$;


