--
-- Name: trend_agg("uuid", integer, "text", "text", interval, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trend_agg"("tenant_id" "uuid", "asset_id" integer, "subtype" "text", "attribute" "text", "raster" interval, "start" timestamp with time zone, "end" timestamp with time zone DEFAULT "now"()) RETURNS SETOF "public"."trend_agg"
    LANGUAGE "plpgsql" STABLE
    AS $_$
DECLARE
    schema_name TEXT := tenant_schema_name($1);
BEGIN
    IF NOT EXISTS (SELECT FROM pg_tables WHERE schemaname = schema_name AND tablename = 'trend') THEN
        RETURN;
    END IF;

    RETURN QUERY EXECUTE format($f$
        SELECT
            asset_id,
            subtype,
            attribute,
            time_bucket($1, ts, current_setting('timezone', true)) AS ts,
            count(value)::float8 AS cnt,
            avg(value),
            sum(value),
            first(value, ts),
            min(value),
            max(value),
            last(value, ts),
            array_agg(DISTINCT change_id) FILTER (WHERE change_id IS NOT NULL),
            array_agg(DISTINCT import_id) FILTER (WHERE import_id IS NOT NULL)
        FROM
            %I.trend
        WHERE
            asset_id = $2
            AND subtype = $3
            AND attribute = $4
            AND ts BETWEEN $5 AND $6
        GROUP BY
            1, 2, 3, 4
        ORDER BY
            ts ASC
    $f$, schema_name)
    USING $5, $2, $3, $4, $6, $7;
END;
$_$;


--
-- Name: trend_agg_cusum("uuid", integer, "text", "text", interval, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."trend_agg_cusum"("tenant_id" "uuid", "asset_id" integer, "subtype" "text", "attribute" "text", "raster" interval, "start" timestamp with time zone, "end" timestamp with time zone DEFAULT "now"()) RETURNS SETOF "public"."trend_agg"
    LANGUAGE "plpgsql" STABLE
    AS $_$
DECLARE
    schema_name TEXT := tenant_schema_name($1);
BEGIN
    IF NOT EXISTS (SELECT FROM pg_tables WHERE schemaname = schema_name AND tablename = 'trend') THEN
        RETURN;
    END IF;

    RETURN QUERY EXECUTE format($f$
        WITH bucketed AS (
            SELECT
                asset_id,
                subtype,
                attribute,
                time_bucket($1, ts, current_setting('timezone', true)) AS ts,
                count(value)::float8 AS cnt,
                min(value),
                max(value),
                last(value, ts),
                array_agg(DISTINCT change_id) FILTER (WHERE change_id IS NOT NULL) AS change_ids,
                array_agg(DISTINCT import_id) FILTER (WHERE import_id IS NOT NULL) AS import_ids
            FROM
                %I.trend
            WHERE
                asset_id = $2
                AND subtype = $3
                AND attribute = $4
                AND ts BETWEEN $5 - $1 AND $6
            GROUP BY
                1, 2, 3, 4
        )
        SELECT
            asset_id,
            subtype,
            attribute,
            ts,
            cnt,
            NULL::float8,
            last - lag(last) OVER (ordered),
            lag(last) OVER (ordered),
            min,
            max,
            last,
            change_ids,
            import_ids
        FROM
            bucketed
        WINDOW
            ordered AS (PARTITION BY asset_id, subtype, attribute ORDER BY ts)
        ORDER BY
            ts ASC
    $f$, schema_name)
    USING $5, $2, $3, $4, $6, $7;
END;
$_$;


--
-- Name: user_notification_but(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."user_notification_but"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.tenant_id = COALESCE(NEW.tenant_id, token_tenant());
    NEW.author_id = token_user();

    -- validate user belongs to tenant
    IF NEW.user_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT FROM public.tenant_user tu
            WHERE tu.tenant_id = NEW.tenant_id AND tu.user_id = NEW.user_id
        ) THEN
            RAISE EXCEPTION 'User % does not belong to tenant %', NEW.user_id, NEW.tenant_id USING ERRCODE = 'PT400';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


