--
-- Name: alarm; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."alarm" (
    "alarm_id" integer NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "asset_id" integer NOT NULL,
    "subtype" "text",
    "attribute" "text",
