    "retention_time" integer DEFAULT 24,
    "cold_storage_time" integer,
    "logfile_lifespan" integer DEFAULT 1,
    "audit_log_limitation" boolean DEFAULT true NOT NULL,
    "trend_mode" "text" DEFAULT 'batch'::"text" NOT NULL,
    "batch_period" integer DEFAULT 100,
    "secret" "text" GENERATED ALWAYS AS ("encode"("public"."digest"((("cust_id" || '.'::"text") || 'c9ce6f35e26dbd72a4eccb071e4f0fd0'::"text"), 'sha256'::"text"), 'hex'::"text")) STORED,
    "iv_attribute" numeric DEFAULT 1,
    "iv_user" numeric DEFAULT 10,
    "iv_connectivity" numeric DEFAULT 100,
    "created_by" "text" DEFAULT (("current_setting"('request.jwt.claims'::"text", true))::"json" ->> 'user_id'::"text"),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "modified_by" "text" DEFAULT (("current_setting"('request.jwt.claims'::"text", true))::"json" ->> 'user_id'::"text"),
    "modified_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "deleted_by" "text",
    CONSTRAINT "eliona_tenant_batch_period_check" CHECK ((("batch_period" IS NULL) OR (("batch_period" >= 10) AND ("batch_period" <= 1000)))),
    CONSTRAINT "eliona_tenant_cold_storage_time_check" CHECK (("cold_storage_time" = ANY (ARRAY[NULL::integer, 1, 3, 6, 12, 24, 36, 48, 60]))),
    CONSTRAINT "eliona_tenant_logfile_lifespan_check" CHECK ((("logfile_lifespan" IS NULL) OR (("logfile_lifespan" >= 1) AND ("logfile_lifespan" <= 12)))),
    CONSTRAINT "eliona_tenant_retention_time_check" CHECK (("retention_time" = ANY (ARRAY[NULL::integer, 1, 3, 6, 12, 24, 36, 48, 60]))),
    CONSTRAINT "eliona_tenant_trend_mode_check" CHECK (("trend_mode" = ANY (ARRAY['plain'::"text", 'batch'::"text", 'smart_batch'::"text"])))
);

