    "down" boolean DEFAULT false NOT NULL,
    "enable" boolean DEFAULT true NOT NULL,
    "asset_id" integer,
    "subtype" "text" NOT NULL,
    "attribute" "text" NOT NULL,
    "scale" double precision,
    "zero" double precision,
    "mask" integer[],
    "mask_attributes" "text"[],
    "dead_time" integer,
    "dead_band" double precision,
    "filter" "public"."filter_mode",
    "tau" double precision
);


--
-- Name: iosys_device; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."iosys_device" (
    "device_id" integer NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "hub_id" integer NOT NULL,
    "enable" boolean DEFAULT false NOT NULL,
    "port" integer DEFAULT 0,
    "certificate" "text",
    "key" "text",
    "timeout" smallint DEFAULT 0,
    "reconnect" smallint DEFAULT 30,
    CONSTRAINT "iosys_device_port_check" CHECK ((("port" >= 0) AND ("port" <= 20))),
    CONSTRAINT "iosys_device_reconnect_check" CHECK ((("reconnect" >= 10) AND ("reconnect" <= 900)))
);


