    CONSTRAINT "opcua_device_timeout_check" CHECK ((("timeout" >= 1000) AND ("timeout" <= 10000)))
);


--
-- Name: connect_hub_statistics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."connect_hub_statistics" AS
 SELECT "opcua_device"."hub_id",
    "count"(DISTINCT "opcua_device"."device_id") AS "device_count",
    "count"(*) FILTER (WHERE ("a"."asset_id" IS NOT NULL)) AS "assets_linked",
    "count"(*) FILTER (WHERE ("a"."asset_id" IS NULL)) AS "assets_unlinked"
   FROM ("public"."opcua_device"
     LEFT JOIN "public"."opcua_access" "a" USING ("device_id"))
  GROUP BY "opcua_device"."hub_id"
UNION ALL
 SELECT "iosys_device"."hub_id",
    "count"(DISTINCT "iosys_device"."device_id") AS "device_count",
    "count"(*) FILTER (WHERE ("a"."asset_id" IS NOT NULL)) AS "assets_linked",
    "count"(*) FILTER (WHERE ("a"."asset_id" IS NULL)) AS "assets_unlinked"
   FROM ("public"."iosys_device"
     LEFT JOIN "public"."iosys_access" "a" USING ("device_id"))
  GROUP BY "iosys_device"."hub_id";


--
-- Name: kafka_bridge; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."kafka_bridge" (
    "hub_id" integer NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    "asset_id" integer,
    "description" "text",
    "client_id" "text",
    "group_id" "text",
    "enable" boolean DEFAULT false NOT NULL,
    "bootstrap_servers" "text"[] NOT NULL,
    "broker_version_fallback" "text",
    "security_protocol" character varying(16),
    "sasl_mechanism" character varying(16),
    "sasl_username" "text",
    "sasl_password" "text",
    "ssl_ca_location" "text",
    "ssl_certificate_location" "text",
    "ssl_key_location" "text",
    CONSTRAINT "kafka_bridge_sasl_mechanism_check" CHECK ((("sasl_mechanism")::"text" = ANY (ARRAY['PLAIN'::"text", 'GSSAPI'::"text", 'SCRAM-SHA-256'::"text", 'SCRAM-SHA-512'::"text"]))),
    CONSTRAINT "kafka_bridge_security_protocol_check" CHECK ((("security_protocol")::"text" = ANY (ARRAY['PLAINTEXT'::"text", 'SASL_PLAINTEXT'::"text", 'SASL_SSL'::"text", 'SSL'::"text"])))
);


--
-- Name: agent; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."agent" AS
 SELECT "kafka_bridge"."hub_id",
    NULL::"uuid" AS "node_id",
    'kafka_bridge'::"text" AS "class",
    "kafka_bridge"."enable",
    "kafka_bridge"."description",
    NULL::"json" AS "config",
    NULL::"json" AS "stat"
   FROM "public"."kafka_bridge"
UNION ALL
 SELECT "connect_hub"."hub_id",
    "connect_hub"."node_id",
    "connect_hub"."class",
    "connect_hub"."enable",
    "connect_hub"."description",
    "connect_hub"."config",
    "json_build_object"('device_count', "connect_hub_statistics"."device_count", 'assets_linked', "connect_hub_statistics"."assets_linked", 'assets_unlinked', "connect_hub_statistics"."assets_unlinked") AS "stat"
   FROM ("public"."connect_hub"
     LEFT JOIN "public"."connect_hub_statistics" USING ("hub_id"));


