--
-- Name: keyauth; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."keyauth" AS
 SELECT "tenant_id",
    "key_id",
    "key",
    EXTRACT(epoch FROM "date_trunc"('second'::"text", "ttl")) AS "expires"
   FROM "public"."keyauth_credentials"
  WHERE ((NOT "revoked") AND
        CASE
            WHEN ("ttl" IS NULL) THEN true
            ELSE ("now"() < "ttl")
        END);


