--
-- Name: dashboard delete_dashboard; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "delete_dashboard" AS
    ON DELETE TO "api"."dashboard" DO INSTEAD  DELETE FROM "public"."dashboard"
  WHERE ("dashboard"."dashboard_id" = "old"."dashboard_id")
  RETURNING "dashboard"."dashboard_id",
    "dashboard"."user_id",
    "dashboard"."template_id",
    "dashboard"."name",
    "dashboard"."config",
    "dashboard"."dashboard_id",
    "dashboard"."public",
    "dashboard"."asset_id";


--
-- Name: tags delete_tags; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "delete_tags" AS
    ON DELETE TO "api"."tags" DO INSTEAD  DELETE FROM "public"."tags"
  WHERE ("tags"."name" = "old"."name")
  RETURNING "tags"."tag_id",
    "tags"."name",
    "tags"."category_id",
    ( SELECT "tag_category"."category"
           FROM "public"."tag_category"
          WHERE ("tag_category"."category_id" = "old"."category_id")) AS "category",
    "tags"."color_id",
    "tags"."custom";


--
-- Name: widget delete_widget; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "delete_widget" AS
    ON DELETE TO "api"."widget" DO INSTEAD  DELETE FROM "public"."widget" "w"
  WHERE (("w"."tenant_id" = "old"."tenant_id") AND ("w"."id" = "old"."id") AND ("public"."token_tenant"() IS NOT NULL))
  RETURNING "old"."id",
    "old"."tenant_id",
    "old"."dashboard_id",
    "old"."type_id",
    "old"."seq",
    "old"."detail",
    "old"."asset_id";


--
-- Name: widget insert_widget; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "insert_widget" AS
    ON INSERT TO "api"."widget" DO INSTEAD  INSERT INTO "public"."widget" ("tenant_id", "dashboard_id", "type_id", "seq", "detail", "asset_id")  SELECT "t"."tenant_id",
            "new"."dashboard_id",
            "new"."type_id",
            "new"."seq",
            "new"."detail",
            "new"."asset_id"
           FROM "public"."token" "t"
          WHERE ("public"."token_tenant"() IS NOT NULL)
  RETURNING "widget"."id",
    "widget"."tenant_id",
    "widget"."dashboard_id",
    "widget"."type_id",
    "widget"."seq",
    "widget"."detail",
    "widget"."asset_id";


--
-- Name: dashboard update_dashboard; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "update_dashboard" AS
    ON UPDATE TO "api"."dashboard" DO INSTEAD  UPDATE "public"."dashboard" SET "name" = "new"."name", "config" = "new"."config", "public" = "new"."public", "asset_id" = "new"."asset_id"
  WHERE ("dashboard"."dashboard_id" = "new"."dashboard_id")
  RETURNING "dashboard"."dashboard_id",
    "dashboard"."user_id",
    "dashboard"."template_id",
    "dashboard"."name",
    "dashboard"."config",
    "dashboard"."dashboard_id",
    "dashboard"."public",
    "dashboard"."asset_id";


--
-- Name: heap update_heap; Type: RULE; Schema: api; Owner: -
--

CREATE RULE "update_heap" AS
    ON UPDATE TO "api"."heap" DO INSTEAD  UPDATE "public"."heap" SET "his" = "new"."his"
   FROM "public"."asset"
  WHERE (("heap"."asset_id" = "old"."asset_id") AND ("heap"."subtype" = "old"."subtype") AND ("asset"."tenant_id" = "heap"."tenant_id") AND ("asset"."asset_id" = "heap"."asset_id"))
  RETURNING "heap"."asset_id",
    "heap"."tenant_id",
    "heap"."subtype",
    "heap"."his",
    "heap"."ts",
    "heap"."data",
    "heap"."update_cnt",
    "asset"."asset_type";


